parameters.jsCode:
const approval = $input.first().json;

/**
 * Confirm that the database returned the token required
 * to open the secure campaign-review page.
 */
const decisionToken = String(
  approval.decision_token ?? ''
).trim();

if (!decisionToken) {
  throw new Error(
    'The approval request did not return a decision token.'
  );
}

/**
 * Public AdFlow Studio website address.
 *
 * During local development:
 * http://localhost:8788
 *
 * After Cloudflare Pages deployment, replace it with:
 * https://adflow-studio.pages.dev
 */
const publicWebAppUrl =
  'http://localhost:8788';

/**
 * Remove any trailing slash so the final URL does not contain //review.
 */
const normalizedBaseUrl =
  publicWebAppUrl.replace(/\/+$/, '');

/**
 * The React website reads the approval token from the route:
 *
 * /review/:token
 *
 * Example:
 * http://localhost:8788/review/abc123...
 */
const reviewUrl =
  `${normalizedBaseUrl}/review/` +
  encodeURIComponent(decisionToken);

/**
 * Return all approval information plus the website review URL.
 *
 * Later nodes, such as Gmail and the revision worker,
 * still receive the original approval fields.
 */
return [
  {
    json: {
      ...approval,

      decision_token: decisionToken,

      review_url: reviewUrl,

      approval_status:
        approval.decision ?? 'pending',

      public_web_app_url:
        normalizedBaseUrl,
    },
  },
];

